/**
* The reference-documentation block of a module README.
*
* `bin/fortran-docs.mjs --readme` writes the routine's reference BLAS/LAPACK
* documentation (Markdown + KaTeX math) into the module's README.md between
* two HTML comments, so it renders on GitHub and travels with the module:
*
*     <!-- fortran-docs:start (generated by bin/fortran-docs.mjs from <source>; do not edit) -->
*
*     <section class="fortran-docs">
*     ...
*     </section>
*
*     <!-- fortran-docs:end -->
*
* `bin/gen_readme.js` carries the block over when it regenerates a README, and
* `bin/docs/extract.js` lifts it into the documentation site.
*
* @module bin/lib/fortran-docs-block
*/

'use strict';

var START_RE = /<!-- fortran-docs:start\b[^>]*-->/;
var END = '<!-- fortran-docs:end -->';
var BLOCK_RE = /\n*<!-- fortran-docs:start\b[^>]*-->[\s\S]*?<!-- fortran-docs:end -->\n*/;

/**
* Returns the full block (markers included) of a README, or null.
*
* @param {string} readme - README text
* @returns {(string|null)} block
*/
function block( readme ) {
	var m = readme.match( BLOCK_RE );
	return m ? m[ 0 ].trim() : null;
}

/**
* Returns the Markdown inside a README's block (no markers, no `<section>` wrapper), or null.
*
* @param {string} readme - README text
* @returns {(string|null)} Markdown
*/
function extract( readme ) {
	var b = block( readme );
	if ( !b ) {
		return null;
	}
	return b.replace( START_RE, '' ).replace( END, '' ).replace( /<section class="fortran-docs">/, '' ).replace( /<\/section>\s*$/, '' ).trim();
}

/**
* Returns the source path named in a README's start marker, or null.
*
* @param {string} readme - README text
* @returns {(string|null)} repository-relative source path
*/
function source( readme ) {
	var m = readme.match( /<!-- fortran-docs:start \(generated by bin\/fortran-docs\.mjs from (\S+);/ );
	return m ? m[ 1 ] : null;
}

/**
* Wraps Markdown in the markers.
*
* @param {string} markdown - block Markdown
* @param {string} src - repository-relative Fortran source path
* @returns {string} block
*/
function wrap( markdown, src ) {
	return '<!-- fortran-docs:start (generated by bin/fortran-docs.mjs from ' + src + '; do not edit) -->\n\n<section class="fortran-docs">\n\n' + markdown.trim() + '\n\n</section>\n\n' + END;
}

/**
* Inserts or replaces the block in a README. A new block goes after the
* examples section (before the `related` and `links` sections), or at the end.
*
* @param {string} readme - README text
* @param {(string|null)} b - block from `wrap()`/`block()`; null removes it
* @returns {string} README text
*/
function upsert( readme, b ) {
	if ( BLOCK_RE.test( readme ) ) {
		// A function replacement: a string one would read `$$` in the math as `$`.
		return readme.replace( BLOCK_RE, function replacement() {
			return b ? '\n\n' + b + '\n\n' : '\n\n';
		});
	}
	if ( !b ) {
		return readme;
	}
	var anchors = [ '<!-- Section for related', '<section class="related">', '<!-- Section for all links', '<section class="links">' ];
	for ( var i = 0; i < anchors.length; i++ ) {
		var k = readme.indexOf( anchors[ i ] );
		if ( k >= 0 ) {
			// Re-run as a replacement so a fresh insert has the same spacing as a refresh.
			return upsert( readme.slice( 0, k ).replace( /\n*$/, '\n\n' ) + b + '\n\n' + readme.slice( k ), b );
		}
	}
	return upsert( readme.replace( /\n*$/, '\n\n' ) + b + '\n', b );
}

module.exports = {
	'block': block,
	'extract': extract,
	'source': source,
	'wrap': wrap,
	'upsert': upsert
};
